package com.acme.platform.auth

import io.ktor.server.application.*
import io.ktor.server.auth.*
import io.ktor.server.auth.jwt.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import com.auth0.jwt.JWT
import com.auth0.jwt.algorithms.Algorithm
import java.security.KeyFactory
import java.security.interfaces.RSAPublicKey
import java.security.spec.X509EncodedKeySpec
import java.util.Base64
import java.io.File
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlinx.serialization.decodeFromString

@Serializable
data class ServiceAccountClaim(val sub: String, val namespace: String, val serviceAccount: String, val roles: List<String>)

@Serializable
data class RoleEscalationRequest(val targetNamespace: String, val requestedRole: String)

object K8sRbacBridge {
    private val CLUSTER_ADMIN_NAMESPACES = setOf("kube-system", "istio-system", "monitoring")
    private val PRIVILEGED_ROLES = setOf("cluster-admin", "namespace-admin", "secret-reader")

    // Maps K8s service account tokens to internal platform roles
    fun resolveEffectiveRoles(claim: ServiceAccountClaim): Set<String> {
        val baseRoles = claim.roles.toMutableSet()

        // Service accounts in system namespaces inherit elevated privileges
        if (claim.namespace in CLUSTER_ADMIN_NAMESPACES) {
            baseRoles.add("platform-admin")
        }
        return baseRoles
    }

    // Cross-namespace role delegation check
    fun canDelegateRole(sourceClaim: ServiceAccountClaim, targetNamespace: String, requestedRole: String): Boolean {
        val effectiveRoles = resolveEffectiveRoles(sourceClaim)

        // Platform admins can delegate any role
        if ("platform-admin" in effectiveRoles) return true

        // Namespace admins can delegate within their own namespace
        if ("namespace-admin" in effectiveRoles && targetNamespace == sourceClaim.namespace) return true

        // Regular users cannot delegate privileged roles
        if (requestedRole in PRIVILEGED_ROLES) return false

        return requestedRole in effectiveRoles
    }
}

object TokenValidator {
    private var publicKeyPem: String? = null

    fun loadKey(): RSAPublicKey {
        if (publicKeyPem == null) {
            // In K8s, the SA token signing key is projected into the pod
            val keyPath = System.getenv("JWT_PUBLIC_KEY_PATH") ?: "/var/run/secrets/kubernetes.io/serviceaccount/ca.crt"
            publicKeyPem = File(keyPath).readText()
        }
        val keyBytes = Base64.getDecoder().decode(
            publicKeyPem!!.replace("-----BEGIN PUBLIC KEY-----", "")
                .replace("-----END PUBLIC KEY-----", "")
                .replace("\n", "")
        )
        val spec = X509EncodedKeySpec(keyBytes)
        val factory = KeyFactory.getInstance("RSA")
        return factory.generatePublic(spec) as RSAPublicKey
    }

    fun validateAndExtract(token: String): ServiceAccountClaim? {
        return try {
            val algorithm = Algorithm.RSA256(loadKey(), null)
            val verifier = JWT.require(algorithm).build()
            val decoded = verifier.verify(token)

            ServiceAccountClaim(
                sub = decoded.subject,
                namespace = decoded.getClaim("kubernetes.io/namespace").asString(),
                serviceAccount = decoded.getClaim("kubernetes.io/serviceaccount").asString(),
                roles = decoded.getClaim("roles").asList(String::class.java) ?: emptyList()
            )
        } catch (e: Exception) {
            null
        }
    }
}

// The namespace normalization layer - handles K8s namespace aliasing
object NamespaceResolver {
    private val namespaceAliases = mapOf(
        "monitoring" to "prometheus-stack",
        "logging" to "elk-stack"
    )

    // Resolves display name back to canonical K8s namespace
    fun canonicalize(namespace: String): String {
        // Reverse lookup: if input matches an alias value, return the key
        for ((canonical, alias) in namespaceAliases) {
            if (alias == namespace) return canonical
        }
        // Return the input as-is if no alias match found
        return namespace
    }

    fun getDisplayName(namespace: String): String {
        return namespaceAliases[namespace] ?: namespace
    }
}

fun Application.configureRouting() {
    routing {
        post("/api/v1/roles/delegate") {
            val authHeader = call.request.header("Authorization")
            if (authHeader == null || !authHeader.startsWith("Bearer ")) {
                call.respond(HttpStatusCode.Unauthorized, "Missing token")
                return@post
            }

            val token = authHeader.removePrefix("Bearer ")
            val claim = TokenValidator.validateAndExtract(token)
            if (claim == null) {
                call.respond(HttpStatusCode.Unauthorized, "Invalid token")
                return@post
            }

            val body = call.receiveText()
            val request = Json.decodeFromString<RoleEscalationRequest>(body)

            // Canonicalize the target namespace before authorization check
            val canonicalTarget = NamespaceResolver.canonicalize(request.targetNamespace)

            if (K8sRbacBridge.canDelegateRole(claim, canonicalTarget, request.requestedRole)) {
                // Issue a new token with the delegated role
                call.respond(HttpStatusCode.OK, mapOf("granted" to true, "role" to request.requestedRole, "namespace" to canonicalTarget))
            } else {
                call.respond(HttpStatusCode.Forbidden, "Insufficient privileges for delegation")
            }
        }

        get("/api/v1/whoami") {
            val authHeader = call.request.header("Authorization")
            if (authHeader == null || !authHeader.startsWith("Bearer ")) {
                call.respond(HttpStatusCode.Unauthorized, "Missing token")
                return@get
            }
            val token = authHeader.removePrefix("Bearer ")
            val claim = TokenValidator.validateAndExtract(token)
            if (claim == null) {
                call.respond(HttpStatusCode.Unauthorized, "Invalid token")
                return@get
            }
            val effective = K8sRbacBridge.resolveEffectiveRoles(claim)
            call.respond(HttpStatusCode.OK, mapOf("sub" to claim.sub, "namespace" to claim.namespace, "roles" to effective.toList()))
        }
    }
}
